"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["44536"],{93924(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.criterio_desempate.parametros_incompativeis_com_regra","status":422,"titulo":"Os par\xe2metros informados n\xe3o correspondem \xe0 regra referenciada"},"descricao":{"codigo":"uniplus.selecao.criterio_desempate.parametros_incompativeis_com_regra","requisitos":["UNI-REQ-0015"],"oQueAconteceu":["Um crit\xe9rio de desempate foi criado com um conjunto de par\xe2metros que n\xe3o\\ncorresponde \xe0 regra referenciada. Por exemplo, par\xe2metros de\\n`DESEMPATE_IDOSO` ligados \xe0 regra `DESEMPATE_MAIOR_NOTA_ETAPA`. O erro aponta o\\ncampo `regraCodigo`.","Esta confer\xeancia \xe9 de seguran\xe7a. Tanto a defini\xe7\xe3o dos crit\xe9rios de desempate\\nquanto a leitura das vers\xf5es j\xe1 publicadas, feita na retifica\xe7\xe3o em ato \xfanico,\\nmontam os par\xe2metros a partir do c\xf3digo da pr\xf3pria regra. Por isso, com o\\ncomportamento atual, a combina\xe7\xe3o errada n\xe3o chega a acontecer em nenhum dos dois\\ncaminhos. A confer\xeancia existe para que a cria\xe7\xe3o do crit\xe9rio n\xe3o dependa de\\nessa correspond\xeancia j\xe1 ter sido garantida em outro lugar."],"comoResolver":["Este erro n\xe3o deveria ocorrer com o comportamento atual do sistema. Se\\naparecer, indica uma inconsist\xeancia interna: um crit\xe9rio chegou \xe0 cria\xe7\xe3o com\\npar\xe2metros que n\xe3o foram montados a partir da pr\xf3pria regra. Informe a equipe\\nt\xe9cnica do Uni+ para investiga\xe7\xe3o; o envio de outros dados no pedido n\xe3o corrige\\no problema."],"ondeAparece":["Defini\xe7\xe3o de crit\xe9rios de desempate do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Criterio desempate"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);